<script lang="ts">
  import { api, resourceValue } from '../api';
  import type { StagedContent, StagedFile } from '../changePlan';
  import type { FileDiff, FileEntry, FileRead } from '../types';
  export let initialUnitId = '';
  export let onUnitChange: (id: string) => void = () => {};
  export let unsupported = false;
  export let csrfAvailable = false;
  export let sessionId = '';
  export let onStageContent: (bytes: number[], classification?: string) => Promise<StagedContent | undefined> = async () => undefined;
  export let onStagedFile: (file: StagedFile) => void = () => {};
  let unitId = initialUnitId; let path = '.'; let files: FileEntry[] = []; let selectedPath = ''; let selectedClassification = 'unknown'; let content = ''; let contentType = 'text/plain'; let readDigest = ''; let diff: FileDiff | undefined; let browseLoading = false; let readLoading = false; let error = ''; let notice = ''; let expectedVersion = ''; let batch: File[] = []; let batchProgress = 0; let stagedRef: StagedContent | undefined; let protectedMetadata = false;
  $: if (initialUnitId && !unitId) unitId = initialUnitId;
  $: readOnlyClassification = !['managed', 'mutable_config', 'artifact', 'generated'].includes(selectedClassification.toLowerCase());
  function unitChanged(event: Event) { unitId = (event.currentTarget as HTMLInputElement).value; onUnitChange(unitId); }
  function endpoint(suffix: string): string { return `/execution-units/${encodeURIComponent(unitId)}/files${suffix}`; }
  async function browse() { if (!unitId) { error = 'Execution Unit id is required.'; return; } browseLoading = true; error = ''; notice = ''; const result = await api<FileEntry[]>(`${endpoint('')}?path=${encodeURIComponent(path || '.')}`); if (result.error) error = result.error.message; else files = result.data ?? []; browseLoading = false; }
  async function read(filePath: string) { if (!unitId) return; selectedPath = filePath; selectedClassification = files.find((file) => file.path === filePath)?.classification || 'unknown'; protectedMetadata = false; readLoading = true; error = ''; notice = ''; diff = undefined; const result = await api<FileRead>(`${endpoint('/read')}?path=${encodeURIComponent(filePath)}`); if (result.error) error = result.error.message; else if (result.data) { contentType = result.data.content_type; protectedMetadata = contentType.split(';', 1)[0].trim().toLowerCase() === 'application/vnd.kitsunebi.secret-metadata'; if (protectedMetadata) { selectedClassification = 'secret'; content = '[protected secret metadata; original content hidden by policy]'; readDigest = files.find((file) => file.path === filePath)?.digest || ''; } else { content = selectedClassification.toLowerCase() === 'secret' ? '[secret content hidden by policy]' : new TextDecoder().decode(new Uint8Array(result.data.content)); readDigest = result.data.content.length ? await digest(result.data.content) : ''; } } readLoading = false; }
  async function showDiff() { if (!unitId || !selectedPath) return; const result = await api<FileDiff>(`${endpoint('/diff')}?path=${encodeURIComponent(selectedPath)}`); if (result.error) error = result.error.message; else diff = result.data; }
  async function download() { if (!unitId || !selectedPath || selectedClassification.toLowerCase() === 'secret') return; error = ''; try { const response = await fetch(`/api/v1${endpoint('/download')}?path=${encodeURIComponent(selectedPath)}`, { credentials: 'same-origin' }); if (!response.ok) { error = `Download failed (${response.status})`; return; } const responseType = (response.headers.get('content-type') ?? '').split(';', 1)[0].trim().toLowerCase(); if (responseType === 'application/vnd.kitsunebi.secret-metadata') { selectedClassification = 'secret'; protectedMetadata = true; contentType = responseType; content = '[protected secret metadata; original content hidden by policy]'; readDigest = files.find((file) => file.path === selectedPath)?.digest || ''; notice = 'Secret metadata is protected; the original file was not downloaded.'; return; } const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = selectedPath.split('/').pop() || 'download'; link.click(); URL.revokeObjectURL(link.href); } catch { error = 'Controller is unreachable'; } }
  async function digest(bytes: number[]): Promise<string> { const hash = await crypto.subtle.digest('SHA-256', new Uint8Array(bytes)); return [...new Uint8Array(hash)].map((byte) => byte.toString(16).padStart(2, '0')).join(''); }
  async function save() {
    if (!sessionId || !csrfAvailable || readOnlyClassification || !selectedPath) { notice = 'Select an editable file and a Change Session before staging.'; return; }
    stagedRef = await onStageContent([...new TextEncoder().encode(content)], selectedClassification);
    if (!stagedRef) { error = 'The controller did not return staged content metadata.'; return; }
    onStagedFile({ sessionId, path: selectedPath, content: stagedRef, classification: selectedClassification, expectedBeforeDigest: readDigest });
    notice = `Staged ${selectedPath} (${stagedRef.size.toLocaleString()} bytes). Add it to a typed file step from Change Sessions.`;
  }
  async function uploadBatch() {
    if (!sessionId || !csrfAvailable || unsupported) { notice = 'Select a Change Session before staging files.'; return; }
    error = ''; notice = ''; batchProgress = 0;
    for (const file of batch) {
      const contentRef = await onStageContent([...new Uint8Array(await file.arrayBuffer())], 'mutable_config');
      if (!contentRef) { error = `Could not stage ${file.name}.`; return; }
      onStagedFile({ sessionId, path: file.name, content: contentRef, classification: 'mutable_config' });
      batchProgress += 1;
    }
    notice = `Staged ${batchProgress} file${batchProgress === 1 ? '' : 's'} in the selected Change Session.`;
  }
</script>

<section class="files-workspace" aria-labelledby="files-title">
  <div class="change-intro"><div><p class="eyebrow">Brokered file observations</p><h2 id="files-title">Files &amp; diff</h2><p>Browse and inspect through Kitsunebi. File changes are staged in a typed ChangePlan; unknown files are never removed automatically.</p></div><span class="endpoint-label">/api/v1/execution-units/&#123;id&#125;/files</span></div>
  {#if unsupported}<div class="state-message info" role="status"><span class="state-mark">·</span><div><strong>File operations disabled by API capability</strong><span>The controller does not expose file access for this scope.</span></div></div>{/if}
  <div class="file-toolbar"><label>Execution Unit<input value={unitId} oninput={unitChanged} placeholder="Execution Unit id" autocomplete="off" /></label><label>Browse path<input bind:value={path} placeholder="." autocomplete="off" /></label><button class="quiet" onclick={browse} disabled={browseLoading || !unitId || unsupported}>{browseLoading ? 'Browsing…' : 'Browse'}</button></div>
  {#if error}<div class="state-message error" role="alert"><span class="state-mark">!</span><div><strong>{unsupported ? 'File capability unavailable' : 'File operation failed'}</strong><span>{error}</span></div></div>{/if}{#if notice}<div class="state-message success" role="status"><span class="state-mark">✓</span><div><strong>Operation observed</strong><span>{notice}</span></div></div>{/if}{#if !csrfAvailable}<div class="state-message info"><span class="state-mark">·</span><div><strong>Writes disabled</strong><span>No same-origin CSRF header is available in this session. Browse, read, diff, and download remain available.</span></div></div>{/if}
  <div class="files-layout"><div class="file-list panel"><div class="panel-head"><div><h3>Entries</h3><p>{files.length ? `${files.length} entries · browse result` : 'No browse result'}</p></div><span class="batch-count">{files.length}/120 visible</span></div>{#if files.length === 0}<div class="list-state"><div class="state-message empty"><span class="state-mark">·</span><div><strong>Browse an execution unit</strong><span>Path validation and file access happen at the API boundary.</span></div></div></div>{:else}<div class="file-entry-list">{#each files.slice(0, 120) as file}<button class:selected={file.path === selectedPath} class="file-entry" onclick={() => read(file.path)}><span class="file-kind">{file.classification}</span><span><strong>{file.path}</strong><small>{file.size.toLocaleString()} bytes · {file.digest.slice(0, 12)}</small></span></button>{/each}</div>{/if}</div><div class="file-editor panel"><div class="panel-head"><div><h3>{selectedPath || 'Select a file'}</h3><p>{selectedPath ? `${contentType} · ${readDigest ? readDigest.slice(0, 16) : 'digest unavailable'}` : 'Read before editing'}</p></div><span class="safety-label">{selectedPath ? `${selectedClassification} · ${readOnlyClassification ? 'read-only' : 'editable'}` : 'read-only'}</span></div>{#if readLoading}<div class="detail-loading"><span class="skeleton-line"></span><span class="skeleton-line"></span></div>{:else if selectedPath}{#if readOnlyClassification}<p class="disabled-reason">{protectedMetadata ? 'Secret metadata is protected; only metadata and the persisted digest are shown.' : selectedClassification.toLowerCase() === 'secret' ? 'Secret content is hidden by policy; only metadata and digest are shown.' : 'Unknown classification is observe-only until the controller classifies this file.'}</p>{/if}<textarea bind:value={content} aria-label="File content" rows="18" spellcheck="false" disabled={readOnlyClassification}></textarea><div class="editor-actions"><button class="quiet" onclick={showDiff}>View diff</button><button class="quiet" onclick={download} disabled={selectedClassification.toLowerCase() === 'secret'}>Download</button><label class="inline-field">If-Match<input bind:value={expectedVersion} placeholder="Required" disabled={readOnlyClassification} /></label><button class="primary" onclick={save} disabled={!sessionId || !csrfAvailable || readOnlyClassification || unsupported}>{sessionId && csrfAvailable ? 'Stage in Change Session' : 'Select a Change Session to stage'}</button></div>{#if stagedRef}<p class="muted-copy">Latest staged ref: {stagedRef.digest} · {stagedRef.size.toLocaleString()} bytes</p>{/if}{#if diff}<div class="diff-result"><strong>{diff.changed ? 'Changed' : 'No change'}</strong><span>before {diff.before_digest ?? '—'} → after {diff.after_digest ?? '—'}</span></div>{/if}{:else}<div class="list-state"><div class="state-message empty"><span class="state-mark">·</span><div><strong>Nothing selected</strong><span>Choose a file to read its content, digest, classification, and diff.</span></div></div></div>{/if}</div></div>
  <div class="upload-strip panel"><div><h3>Stage file batch</h3><p>Select files to prepare a typed ChangePlan file step; apply happens from Change Sessions.</p></div><input type="file" multiple disabled={unsupported || !sessionId || !csrfAvailable} onchange={(event) => { batch = [...((event.currentTarget as HTMLInputElement).files ?? [])].slice(0, 120); }} /><span>{batch.length}/120 selected</span>{#if batchProgress}<progress max={batch.length} value={batchProgress}>{batchProgress}/{batch.length}</progress>{/if}<button class="primary" onclick={uploadBatch} disabled={!batch.length || unsupported || !sessionId || !csrfAvailable}>Stage in Change Session</button></div>
</section>
